02-if-e-else.md.correcao:
temperatura = int(input("Temperatura: "))
# A temperatura 20 pertence ao segundo caminho.
if temperatura < 20:
    print("Frio")
else:
    print("Agradável")

03-varios-caminhos-elif.md.correcao:
nota = int(input("Nota: "))
# Verifique primeiro a faixa mais alta, que também satisfaz nota >= 7.
if nota >= 9:
    print("Excelente")
elif nota >= 7:
    print("Aprovado")
else:
    print("Estude mais")

05-oficina-decisoes.md.correcao:
nota = float(input("Nota: "))
# Confira as duas fronteiras antes de aplicar a regra de aprovação.
if nota < 0 or nota > 10:
    print("Nota inválida")
elif nota >= 7:
    print("Aprovado")
else:
    print("Recuperação")
